package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RelatedCalculationFactsTest {
 @Test public void twoStrategiesFreshSupplyAndPublicChecks(){for(String id:List.of(RelatedCalculationFacts.ADD,RelatedCalculationFacts.SUB)){var limits=GlobalCurriculum.limits("england-primary-2021-v1",id,2);var pool=RelatedCalculationFacts.pool(id,limits);assertTrue(pool.size()>100);Generator g=new Generator(new Random(117));List<String> recent=new ArrayList<>();boolean scaled=false,shifted=false;for(int i=0;i<100;i++){Question q=g.next(id,recent,true,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());String[] lines=q.prompt.split("\n"),original=lines[0].substring("아는 계산: ".length()).split(" [+−=] "),target=lines[1].split(" [+−=] ");int a=Integer.parseInt(original[0]),b=Integer.parseInt(original[1]),c=Integer.parseInt(original[2]),A=Integer.parseInt(target[0]),B=Integer.parseInt(target[1]);boolean add=id.equals(RelatedCalculationFacts.ADD),scale=A==a*10&&B==b*10;int result=add?A+B:A-B;assertEquals(add?a+b:a-b,c);assertTrue(c>=0&&c<=20&&A<=100&&B<=100&&result>=0&&result<=100);if(scale)scaled=true;else{shifted=true;assertEquals(b,B);assertTrue(A-a>=10&&(A-a)%10==0);}q.answers=new String[]{"poison"};q.expression="wrong";Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of(""+result)).correct());assertEquals(0,checker.check(q,List.of(),List.of(""+(result+1))).index);HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(scale?5:3,h.size());String[] values=scale?new String[]{""+c,"10",""+A,""+B,""+result}:new String[]{""+c,""+(A-a),""+result};for(int j=0;j<h.size();j++){assertTrue(h.step(j).accepts(values[j]));assertFalse(h.step(j).before.matches(".*\\d.*"));}assertTrue(q.choices.isEmpty());}assertTrue(scaled&&shifted);Map<String,Integer> ages=new HashMap<>();for(String key:pool.keySet())ages.put(key,10);String oldest=pool.keySet().iterator().next();ages.put(oldest,1);assertEquals(oldest,RelatedCalculationFacts.next(Catalog.get(id),new Random(1),limits,ages).signature());}}
 @Test public void zeroBoundariesAndMalformedKnownFacts(){for(String id:List.of(RelatedCalculationFacts.ADD,RelatedCalculationFacts.SUB)){boolean add=id.equals(RelatedCalculationFacts.ADD);for(int[] args:new int[][]{{0,0,100,0},{9,0,10,1},{10,10,80,0},{10,10,10,1}}){if(add&&args[3]==1&&args[0]+args[1]>10)continue;Question q=RelatedCalculationFacts.make(id,args[0],args[1],args[2],args[3]==1);HelpPlan.forQuestion(q);assertNotNull(q.studyGuide);assertFalse(q.studyGuide.transfer);int[] v=RelatedCalculationFacts.read(q);assertTrue(new Checker().check(q,List.of(),List.of(""+v[5])).correct());assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("1+2")).status);q.prompt=q.prompt.replace("아는 계산:","invalid");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}}
  Question falseFact=new Question(RelatedCalculationFacts.ADD,"아는 계산: 3 + 5 = 7\n30 + 50 = □","","80");assertNull(RelatedCalculationFacts.read(falseFact));
 }
}
